      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A fluorinated oxindole analogue with methoxy and trifluoromethyl groups reached brain-to-plasma ratios of approximately 7–11 in rats, showing that related lipophilic heteroaromatics can have high CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A methoxy-substituted TSPO ligand achieved 2.1–3.5% ID/g brain radioactivity in mice, confirming that methoxy/fluoroaryl analogues in this series cross the BBB.",
